const ENV = {...process.env, USERPROFILE:"C:\\Users\\a7med", APPDATA:"C:\\Users\\a7med\\AppData\\Roaming", LOCALAPPDATA:"C:\\Users\\a7med\\AppData\\Local", HOME:"C:\\Users\\a7med", SYSTEMROOT:"C:\\Windows"};
const run = (cmd) => new Promise((res) => {
  cp.exec(cmd, { shell:"C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe", env: ENV, maxBuffer: 30*1024*1024, timeout: 240000 }, (e, so, se) => res({ code: e?.code, out: so, err: se }));
});
const r = await run(`
$roots = @('D:\\Projects\\_SIR\\_local','D:\\Projects\\SIR AI','D:\\Projects\\AHome','D:\\Projects\\_SIR\\scripts','D:\\Projects\\_SIR\\ops')
$files = Get-ChildItem -Path $roots -Recurse -File -Include '*.env','*.json','*.txt','*.py','*.mjs','*.md' -ErrorAction SilentlyContinue | Where-Object { $_.FullName -notmatch 'node_modules|.venv|\\\\.git\\\\|agy-runs|prompt-|reply-|chat.jsonl' }
$pattern = '\\d{8,10}:[A-Za-z0-9_-]{35}'
$hits = @()
foreach ($f in $files) {
  try { $c = Get-Content $f.FullName -Raw -ErrorAction Stop } catch { continue }
  $ms = [regex]::Matches($c, $pattern)
  if ($ms.Count -gt 0) {
    foreach ($m in $ms) { $hits += [pscustomobject]@{ File=$f.FullName; Token=$m.Value } }
  }
}
$hits | Group-Object Token | ForEach-Object {
  $tok = $_.Name
  $short = $tok.Substring(0,10) + '...' + $tok.Substring($tok.Length-4)
  $fileList = ($_.Group | Select-Object -ExpandProperty File -Unique) -join ' | '
  Write-Output ("TOKEN $short  count=$($_.Count)  in: $fileList")
}
`);
console.log(r.out.slice(0,8000));", "description": "Inventory Telegram bot tokens on disk"}

