const payload = "C:\\Program Files\\WindowsApps\\NousResearchInc.HermesAgent_2026.7512.1650.0_x64__sznbd6dv1j3v4\\app\\resources\\agent-payload";
const ENV = {...process.env, USERPROFILE:"C:\\Users\\a7med", APPDATA:"C:\\Users\\a7med\\AppData\\Roaming", LOCALAPPDATA:"C:\\Users\\a7med\\AppData\\Local", HOME:"C:\\Users\\a7med", SYSTEMROOT:"C:\\Windows", HERMES_HOME:"C:\\Users\\a7med\\AppData\\Local\\hermes", PYTHONIOENCODING:"utf-8", HERMES_ACCEPT_HOOKS:"1"};
const exe = payload+"\\bin\\hermes.exe";
// stream spawn so we can see partial output
const runStream = (args, ms) => new Promise((res) => {
  const p = cp.spawn(exe, args, { env: ENV, windowsHide: true });
  let out = "", err = "";
  p.stdout.on("data", d => out += d.toString());
  p.stderr.on("data", d => err += d.toString());
  const t = setTimeout(() => { try { p.kill(); } catch{}; res({ timeout: true, out, err }); }, ms);
  p.on("exit", (code) => { clearTimeout(t); res({ code, out, err }); });
  p.on("error", (e) => { clearTimeout(t); res({ error: e.message, out, err }); });
});
const r = await runStream(["doctor"], 90000);
console.log("TIMEOUT?", r.timeout, "code", r.code, "err", r.error);
console.log("OUT:\n"+(r.out||"").slice(0,6000));
console.log("ERR:\n"+(r.err||"").slice(0,3000));", "description": "Run hermes doctor with streamed output"}

